import fs from "node:fs";
import path from "node:path";
import { logger } from "../logger";
import type { CfModule, CfWorkerSourceMap } from "@cloudflare/workers-utils";

interface SourceMapMetadata {
	tmpDir: string;
	entryDirectory: string;
}

export interface SourceMapBundle {
	sourceMapPath?: string | undefined;
	sourceMapMetadata?: SourceMapMetadata | undefined;
	[key: string]: unknown;
}

/**
 * Loads source maps that appear in the given build output.
 *
 * @param main The main module of the Worker.
 * @param modules Any additional modules of the Worker.
 * @param bundle Source map location metadata from Wrangler's bundler, if it ran.
 * @param options.strict When `false`, modules whose source map comment can't be
 * resolved are skipped rather than failing. Used when source maps are uploaded
 * by default rather than explicitly requested.
 * @returns The source maps to upload alongside the Worker.
 */
export function loadSourceMaps(
	main: CfModule,
	modules: CfModule[],
	bundle: SourceMapBundle,
	{ strict = true }: { strict?: boolean } = {}
): CfWorkerSourceMap[] {
	const { sourceMapPath, sourceMapMetadata } = bundle;
	if (sourceMapPath && sourceMapMetadata) {
		// This worker was bundled by Wrangler, so we already know where
		// the source map is located.
		return loadSourceMap(main, sourceMapPath, sourceMapMetadata);
	} else {
		// Don't know where source maps are located, so need to find
		// them by scanning the contents of the user-specified modules.
		return scanSourceMaps([main, ...modules], strict);
	}
}

/**
 * Load and normalize a source map emitted by Wrangler using the given path and
 * directory metadata.
 */
function loadSourceMap(
	{ name, filePath }: CfModule,
	sourceMapPath: string,
	{ entryDirectory }: SourceMapMetadata
): CfWorkerSourceMap[] {
	if (filePath === undefined) {
		return [];
	}

	// esbuild reports output paths relative to the entry directory, except when
	// no relative path exists (e.g. an `--outdir` on another Windows drive),
	// in which case the path is absolute.
	const resolvedSourceMapPath = path.resolve(entryDirectory, sourceMapPath);
	const map = JSON.parse(
		fs.readFileSync(resolvedSourceMapPath, "utf8")
	) as RawSourceMap;
	// Overwrite the file property of the source map to match the name of the
	// main module in the multipart upload.
	map.file = name;
	if (map.sourceRoot) {
		// Remove the temporary directory prefix generated by Wrangler that appears
		// in the source root path.
		const sourceRootPath = path.dirname(resolvedSourceMapPath);
		map.sourceRoot = path.relative(sourceRootPath, map.sourceRoot);
	}
	map.sources = map.sources.map((source) => {
		const originalPath = path.join(path.dirname(filePath), source);
		return path.relative(entryDirectory, originalPath);
	});
	return [
		{
			name: name + ".map",
			content: JSON.stringify(map),
		},
	];
}

/**
 * Find source maps by scanning module contents for special `//#
 * sourceMappingURL=` comments pointing to source map files.
 */
function scanSourceMaps(
	modules: CfModule[],
	strict: boolean
): CfWorkerSourceMap[] {
	const maps: CfWorkerSourceMap[] = [];
	for (const module of modules) {
		const maybeSourcemap = strict
			? sourceMapForModule(module)
			: trySourceMapForModule(module);
		if (maybeSourcemap) {
			maps.push(maybeSourcemap);
		}
	}
	return maps;
}

function trySourceMapForModule(
	module: CfModule
): CfWorkerSourceMap | undefined {
	try {
		return sourceMapForModule(module);
	} catch (error) {
		logger.debug(
			`Skipping source map for ${module.name}: ${error instanceof Error ? error.message : String(error)}`
		);
		return undefined;
	}
}

/**
 * Loads the source maps named by the `sourceMappingURL` custom sections of the
 * Worker's WebAssembly modules.
 *
 * @param modules The modules of the Worker. Only `compiled-wasm` modules are read.
 * @returns The source maps to upload alongside the Worker.
 */
export function loadWasmSourceMaps(modules: CfModule[]): CfWorkerSourceMap[] {
	const maps: CfWorkerSourceMap[] = [];
	for (const module of modules) {
		if (module.type !== "compiled-wasm" || module.filePath === undefined) {
			continue;
		}
		const sourceMapUrl = getWasmSourceMappingUrl(module);
		if (sourceMapUrl !== undefined) {
			maps.push(readSourceMap(module, module.filePath, sourceMapUrl));
		}
	}
	return maps;
}

/**
 * Attaches a sourcemap, if found, to a JavaScript module.
 */
export function tryAttachSourcemapToModule(module: CfModule) {
	if (module.type !== "esm" && module.type !== "commonjs") {
		return;
	}

	const sourceMap = sourceMapForModule(module);
	if (sourceMap) {
		module.sourceMap = sourceMap;
	}
}

function getSourceMappingUrl(module: CfModule): string | undefined {
	const content =
		typeof module.content === "string"
			? module.content
			: new TextDecoder().decode(module.content);

	const commentPrefix = "//# sourceMappingURL=";

	// Scan trailing lines from the bottom up so that the `//# sourceMappingURL=`
	// comment is still detected when other magic comments (e.g.
	// `//# debugId=` injected by `sentry-cli sourcemaps inject`) follow it.
	const lines = content.split("\n");
	for (let i = lines.length - 1; i >= 0; i--) {
		const line = lines[i].trim();
		if (line.length === 0) {
			continue;
		}
		if (line.startsWith(commentPrefix)) {
			// Assume the source map path in the comment is relative to the
			// generated file it appears in.
			const commentPath = stripPrefix(commentPrefix, line).trim();
			if (commentPath.startsWith("data:")) {
				throw new Error(
					`Unsupported source map path in ${module.filePath}: expected file path but found data URL.`
				);
			}
			return commentPath;
		}
		// Skip past other trailing magic comments (`//# debugId=`, `//# sourceURL=`,
		// etc.) and keep looking for the `//# sourceMappingURL=` comment above them.
		// Stop as soon as we hit any non-magic-comment content.
		if (!line.startsWith("//#") && !line.startsWith("//@")) {
			return undefined;
		}
	}

	return undefined;
}

/**
 * Reads the URL in a WebAssembly module's `sourceMappingURL` custom section,
 * if it has one (https://tc39.es/ecma426/).
 */
function getWasmSourceMappingUrl(module: CfModule): string | undefined {
	const bytes = module.content;
	if (
		typeof bytes === "string" ||
		bytes.length < 8 ||
		bytes.readUInt32LE(0) !== 0x6d736100
	) {
		return undefined;
	}
	let pos = 8; // Skip the magic number and version.
	// Reads an unsigned LEB128 integer, as used for sizes and name lengths.
	const readU32 = () => {
		let result = 0;
		for (let shift = 0; shift < 35; shift += 7) {
			if (pos >= bytes.length) {
				return undefined;
			}
			const byte = bytes[pos++];
			result += (byte & 0x7f) * 2 ** shift;
			if ((byte & 0x80) === 0) {
				return result;
			}
		}
		return undefined;
	};
	const readName = (end: number) => {
		const length = readU32();
		if (length === undefined || pos + length > end) {
			return undefined;
		}
		const name = new TextDecoder().decode(bytes.subarray(pos, pos + length));
		pos += length;
		return name;
	};
	while (pos < bytes.length) {
		const id = bytes[pos++];
		const size = readU32();
		if (size === undefined || pos + size > bytes.length) {
			return undefined;
		}
		const end = pos + size;
		// Custom sections have id 0 and start with their name.
		if (id === 0 && readName(end) === "sourceMappingURL") {
			const url = readName(end);
			if (url?.startsWith("data:")) {
				throw new Error(
					`Unsupported source map path in ${module.filePath}: expected file path but found data URL.`
				);
			}
			return url;
		}
		pos = end;
	}
	return undefined;
}

function sourceMapForModule(module: CfModule): CfWorkerSourceMap | undefined {
	if (module.filePath === undefined) {
		// virtual modules don't have sourcemaps so we can exit early here
		return undefined;
	}

	const sourceMapUrl = getSourceMappingUrl(module);
	if (sourceMapUrl === undefined) {
		return;
	}
	return readSourceMap(module, module.filePath, sourceMapUrl);
}

/**
 * Reads the source map at `sourceMapUrl`, relative to the module at
 * `filePath`, and names it after the module in the multipart upload.
 */
function readSourceMap(
	module: CfModule,
	filePath: string,
	sourceMapUrl: string
): CfWorkerSourceMap {
	// Convert source map path to an absolute path that we can read.
	const sourcemapPath = path.join(path.dirname(filePath), sourceMapUrl);
	if (!fs.existsSync(sourcemapPath)) {
		throw new Error(
			`Invalid source map path in ${filePath}: ${sourcemapPath} does not exist.`
		);
	}
	const map = JSON.parse(
		fs.readFileSync(sourcemapPath, "utf8")
	) as RawSourceMap;
	// Overwrite the file property of the sourcemap to match the name of the
	// corresponding module in the multipart upload.
	map.file = module.name;
	if (map.sourceRoot) {
		map.sourceRoot = cleanPathPrefix(map.sourceRoot);
	}
	map.sources = map.sources.map(cleanPathPrefix);
	return {
		name: module.name + ".map",
		content: JSON.stringify(map),
	};
}

/**
 * Removes leading "." and ".." segments from the given file path.
 */
function cleanPathPrefix(filePath: string): string {
	// Don't assume that the path separator matches the current OS.
	return stripPrefix(
		"..\\",
		stripPrefix("../", stripPrefix(".\\", stripPrefix("./", filePath)))
	);
}

function stripPrefix(prefix: string, input: string): string {
	let stripped = input;
	while (stripped.startsWith(prefix)) {
		stripped = stripped.slice(prefix.length);
	}
	return stripped;
}

/**
 * Minimal source map type — only the fields used by this module.
 */
interface RawSourceMap {
	file?: string;
	sourceRoot?: string;
	sources: string[];
}
